"""Backend registry with plugin discovery, priorities, and aliases."""
from importlib import metadata

from export.csv_backend import to_csv
from export.json_backend import to_json


class BackendRegistry:
    def __init__(self):
        self._backends = {}
        self._aliases = {}
        self._priorities = {}

    def register(self, name, backend, priority=0, aliases=()):
        self._backends[name] = backend
        self._priorities[name] = priority
        for alias in aliases:
            self._aliases[alias] = name

    def discover(self, group="export.backends"):
        for entry in metadata.entry_points().select(group=group):
            self.register(entry.name, entry.load())

    def get(self, name):
        name = self._aliases.get(name, name)
        return self._backends[name]

    def by_priority(self):
        return sorted(self._backends, key=lambda n: -self._priorities[n])


registry = BackendRegistry()
registry.register("csv", to_csv, priority=10, aliases=("text/csv",))
registry.register("json", to_json, priority=5, aliases=("application/json",))
registry.discover()

