import re

UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400, "w": 604800}
TOKEN = re.compile(r"(\d+)([a-z])")


def parse_duration(text):
    """Return seconds for strings like 2d1h30m."""
    total = 0
    for match in TOKEN.finditer(text.strip().lower()):
        number, unit = match.groups()
        total += int(number) * UNITS.get(unit, 0)
    return total

